#[derive(Clone, Eq, PartialEq, Debug)]
enum VarType {
    Attr(Name, Namespace),
    Custom(Name),
    NonCustom(SingleNonCustomReference),
}

impl VarType {
    fn namespace(&self) -> Option<&Namespace> {
        match self {
            Self::Attr(_, namespace) => Some(namespace),
            _ => None,
        }
    }
}
